import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

transposed_conv2d_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// Naive transposed convolution kernel
__global__ void transposed_conv2d_kernel(
    const float* input,     // (N, C_in, H_in, W_in)
    const float* weight,    // (C_in, C_out, kH, kW)
    const float* bias,      // (C_out) or dummy if not used
    float* output,          // (N, C_out, H_out, W_out)
    int N,
    int C_in,
    int H_in,
    int W_in,
    int C_out,
    int kH,
    int kW,
    int strideH,
    int strideW,
    int padH,
    int padW,
    int H_out,
    int W_out,
    bool use_bias)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C_out * H_out * W_out;
    if (idx >= total) return;

    // Decompose idx into n, oc, oh, ow
    int ow = idx % W_out;
    int tmp = idx / W_out;
    int oh = tmp % H_out;
    tmp /= H_out;
    int oc = tmp % C_out;
    int n  = tmp / C_out;

    float val = 0.0f;
    // Accumulate contributions from input and weight
    for(int ic = 0; ic < C_in; ic++){
        for(int kh = 0; kh < kH; kh++){
            for(int kw_ = 0; kw_ < kW; kw_++){
                // Transposed convolution index mapping
                int in_h = oh + padH - kh;
                int in_w = ow + padW - kw_;
                if((in_h % strideH == 0) && (in_w % strideW == 0)){
                    in_h /= strideH;
                    in_w /= strideW;
                    if(in_h >= 0 && in_h < H_in && in_w >= 0 && in_w < W_in){
                        int input_index = ((n * C_in + ic) * H_in + in_h) * W_in + in_w;
                        int weight_index = ((ic * C_out + oc) * kH + kh) * kW + kw_;
                        val += input[input_index] * weight[weight_index];
                    }
                }
            }
        }
    }
    if(use_bias){
        val += bias[oc];
    }
    int out_index = ((n * C_out + oc) * H_out + oh) * W_out + ow;
    output[out_index] = val;
}

torch::Tensor transposed_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int strideH,
    int strideW,
    int padH,
    int padW,
    bool use_bias)
{
    // Assumes float tensors on CUDA
    const auto N = input.size(0);
    const auto C_in = input.size(1);
    const auto H_in = input.size(2);
    const auto W_in = input.size(3);

    const auto kH = weight.size(2);
    const auto kW = weight.size(3);
    const auto C_out = weight.size(1);

    // Output size calculation for transposed conv
    const int H_out = (H_in - 1) * strideH - 2 * padH + kH;
    const int W_out = (W_in - 1) * strideW - 2 * padW + kW;

    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto output = torch::zeros({N, C_out, H_out, W_out}, options);

    int total = N * C_out * H_out * W_out;
    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    transposed_conv2d_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N,
        C_in,
        H_in,
        W_in,
        C_out,
        kH,
        kW,
        strideH,
        strideW,
        padH,
        padW,
        H_out,
        W_out,
        use_bias
    );

    return output;
}
'''

transposed_conv2d_cpp_source = r'''
torch::Tensor transposed_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int strideH,
    int strideW,
    int padH,
    int padW,
    bool use_bias
);
'''

# Build/load the custom CUDA extension
transposed_conv2d = load_inline(
    name="transposed_conv2d",
    cpp_sources=transposed_conv2d_cpp_source,
    cuda_sources=transposed_conv2d_source,
    functions=["transposed_conv2d_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    A custom transposed convolution using a naive CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.use_bias = bias

        kH, kW = kernel_size
        # For nn.ConvTranspose2d in PyTorch, weight shape is (in_channels, out_channels, kH, kW)
        self.weight = nn.Parameter(torch.randn(in_channels, out_channels, kH, kW))
        if bias:
            self.bias = nn.Parameter(torch.randn(out_channels))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        b = self.bias if self.use_bias else torch.zeros((1,), device=x.device, dtype=x.dtype)
        return transposed_conv2d.transposed_conv2d_cuda(
            x,
            self.weight,
            b,
            self.stride[0],
            self.stride[1],
            self.padding[0],
            self.padding[1],
            self.use_bias
        )
